insert into public.site_settings (key, value, is_public) values ('cost_model', '{"LPG price (commercial cylinder)": 103.0, "Electricity per box": 1.5, "Wastage and trimming loss": 0.05, "Delivery cost per order (own EV bike)": 4.0, "Payment gateway fee (incl. GST)": 0.024, "Notional labour per box": 25.0, "Dip add-on price": 15.0, "packaging": {"5-compartment tray with lid": 16.0, "Chapati foil / paper wrap": 2.0, "Carry bag": 3.0, "Label sticker (macros, FSSAI)": 2.0, "Tissue + spoon/fork": 3.0, "Packaging per Non-Veg box": 26.0, "Curd cup + lid (Veg boxes only)": 3.0, "Packaging per Veg box": 29.0}, "raw_material_prices": {"Chicken boneless breast": 360.0, "Mackerel (whole fish)": 240.0, "Paneer": 340.0, "Tofu (firm)": 300.0, "Button mushroom": 220.0, "Egg": 6.0, "Egg equivalent (50 g per egg)": 120.0, "Curd (dahi)": 70.0, "Soya chunks (dry)": 130.0, "Sweet corn": 70.0, "Cabbage / carrot / cucumber": 32.0, "Mixed salad vegetables": 45.0, "Broccoli": 140.0, "Whole wheat atta": 45.0, "Rolled oats": 140.0, "Black chana (dry)": 110.0, "Horse gram (dry)": 110.0, "Green gram (dry)": 120.0, "Raw peanut": 130.0, "Kidney beans (dry)": 150.0, "Green peas (frozen or fresh)": 120.0, "Chickpea (dry, for hummus)": 110.0}}'::jsonb, false)
