-- Add-ons: dips at ₹15 (workbook), sides + drinks (data/sides.json, data/addons.json)
insert into public.addons (type, slug, name, description, price, calories, protein, carbs, fat, sugar_g, volume_ml, is_veg, tags, image_url, sort_order)
select type::public.addon_type, slug, name, description, price, calories, protein, carbs, fat, sugar_g, volume_ml, is_veg, tags, image_url, sort_order from (values
  ('side', 'dip-hummus', 'Hummus', '40 g dip, optional extra', 15, 95, 3.5, 8, 5.5, null::numeric, null::int, true, array['Dip', 'Sesame']::text[], null, 100),
  ('side', 'dip-green-chutney', 'Green chutney', '30 g dip, optional extra', 15, 35, 1, 3, 2.2, null::numeric, null::int, true, array['Dip']::text[], null, 101),
  ('side', 'grilled-chicken-with-salad', 'Grilled Chicken with Salad', 'Herb-rubbed chicken breast fillets seared over a hot skillet, paired with crisp shaved cucumber and mint greens. Perfect quick protein booster.', 189, 260, 38, 4, 10, null, null, false, array['High Protein', 'Low Carb', 'Chicken', 'Non-Veg', 'Lab Verification Pending']::text[], 'https://images.unsplash.com/photo-1532550907401-a500c9a57435?auto=format&fit=crop&w=600&q=80', 0),
  ('side', 'chicken-salad', 'Chicken Salad', 'Tender pulled chicken tossed with julienned peppers, sweet radish, and our cold-pressed lemon-pepper dressing. Light, crunchy, and satiating.', 169, 230, 28, 6, 10, null, null, false, array['Lean', 'Salad', 'Chicken', 'Non-Veg', 'Lab Verification Pending']::text[], 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=600&q=80', 1),
  ('side', 'chicken-post-workout-meal', 'Chicken Post Workout Meal', 'Post-workout recovery fuel: 160g char-grilled chicken breast, 100g hand-pounded steamed red rice, and seasonal fresh antioxidant fruit slices.', 229, 450, 42, 48, 10, null, null, false, array['Post-Workout', 'Glycogen Reload', 'Chicken', 'Non-Veg', 'Lab Verification Pending']::text[], 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80', 2),
  ('side', 'grilled-paneer-with-salad', 'Grilled Paneer with Salad', 'Thick farm-fresh cottage cheese slabs seared with dry roasted cumin, served alongside a zesty garden slaw. Vegetarian muscle support.', 179, 300, 22, 6, 21, null, null, true, array['High Protein', 'Vegetarian', 'Paneer', 'Lab Verification Pending']::text[], 'https://images.unsplash.com/photo-1631452180519-c014fe946bc7?auto=format&fit=crop&w=600&q=80', 3),
  ('side', 'paneer-salad', 'Paneer Salad', 'Diced malai paneer cubes marinated in crushed coriander and lime, nestled in baby greens, cherry tomatoes, and cold-pressed oil.', 159, 250, 17, 8, 17, null, null, true, array['Light', 'Vegetarian', 'Paneer', 'Lab Verification Pending']::text[], 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=600&q=80', 4),
  ('side', 'paneer-post-workout-meal', 'Paneer Post Workout Meal', 'Plant-strong replenishment: pan-browned artisanal paneer cubes paired with 100g roasted sweet potato wedges and juicy seasonal melon cubes.', 219, 480, 28, 52, 18, null, null, true, array['Post-Workout', 'Vegetarian', 'Paneer', 'Recovery', 'Lab Verification Pending']::text[], 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=600&q=80', 5),
  ('drink', 'drink-beetroot', 'Beetroot Juice', 'Fresh cold-pressed local beetroot extract with a touch of ginger and lemon.', 59, 85, 2, 19, 0, 14, 250, true, array['Cold-Pressed', 'Zero Added Sugar', 'Veg']::text[], 'https://images.unsplash.com/photo-1546173159-315724a31696?auto=format&fit=crop&w=600&q=80', 50),
  ('drink', 'drink-cucumber', 'Cucumber Juice', 'Crisp fresh polyhouse cucumbers crushed with rock salt.', 49, 35, 1, 7, 0, 4, 250, true, array['Ultra-Light', 'Zero Added Sugar', 'Hydrating', 'Veg']::text[], 'https://images.unsplash.com/photo-1603569283847-aa295f0d016a?auto=format&fit=crop&w=600&q=80', 51),
  ('drink', 'drink-mint-lime', 'Mint Lime', 'Freshly squeezed lime with crushed wild mint leaves.', 49, 40, 1, 8, 0, 4, 250, true, array['Fresh', 'Zero Added Sugar', 'Hydrating', 'Veg']::text[], 'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?auto=format&fit=crop&w=600&q=80', 52),
  ('drink', 'drink-carrot', 'Carrot Juice', 'Slow-juiced fresh mountain carrots from Nilgiri farms.', 69, 90, 2, 21, 0, 16, 250, true, array['Cold-Pressed', 'Zero Added Sugar', 'Beta-Carotene', 'Veg']::text[], 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=600&q=80', 53)
) v(type, slug, name, description, price, calories, protein, carbs, fat, sugar_g, volume_ml, is_veg, tags, image_url, sort_order)
on conflict (slug) do nothing;

-- Plans (data/plans.json + a 1-day trial). Weekly = 6 operating days, monthly = 24.
insert into public.plans (slug, name, type, meals_per_day, operating_days, tagline, description, features, ideal_for, badge, is_popular, sort_order)
select slug, name, type::public.plan_type, mpd, days, tagline, description, features, ideal_for, badge, popular, sort from (values
  ('daily-trial', 'Daily Trial', 'trial', 1, 1, 'Try one box for a single day.', 'Single-day prepaid order. A first taste of BroTin Box.', '[]'::jsonb, '[]'::jsonb, null, false, 0),
  ('6-day-weekly', '6-Day Weekly Plan', 'weekly', 1, 6, 'One fixed measured protein box every day (Mon-Sat, Sunday off).', 'Perfect for busy professionals in Coimbatore. One daily box cooked fresh each morning, matching the fixed kitchen cook schedule.', '["1 box/day following fixed Mon-Sat rotation (Sunday kitchen closed)", "Daily calories & protein printed on every box", "Egg-free & legume customizations saved to your profile", "9:00 PM previous-night cutoff for zero food waste", "Free doorstep delivery across Coimbatore"]'::jsonb, '["Healthy breakfasts", "Busy evenings", "First-time subscribers"]'::jsonb, null, false, 1),
  ('12-meal-weekly', '12-Meal Weekly Plan', 'weekly', 2, 6, 'Complete morning + dinner daily nutrition with 10% weekly discount.', 'Our most popular operational plan: 2 boxes per day (Morning & Dinner). Eat the scheduled day box twice or pair with an alternate day box.', '["2 boxes/day (Morning 7:00-9:00 AM & Dinner 7:00-9:00 PM)", "Built-in 2nd meal discount (₹10 off each second meal)", "Customizable egg-free or extra side add-on bundles", "Pause or skip any day up to 9 PM night before", "Dedicated WhatsApp nutritionist support"]'::jsonb, '["Active gym goers", "Busy founders & techies", "Muscle gain seekers"]'::jsonb, 'Most Popular', true, 2),
  ('24-day-monthly', '24-Day Monthly Plan', 'monthly', 1, 24, 'Full month consistent habit: 24 cooking-free days with maximum savings.', 'Lock in 4 full weeks of predictable, lab-calibrated nutrition. UPI AutoPay supported with single-tap pause whenever you travel.', '["24 daily boxes delivered across 4 working weeks (Mon-Sat)", "Maximum monthly discount applied (₹269/meal)", "Roll over skipped days without losing payment", "Weekly add-on juice or side bundle eligible", "Free doorstep delivery across Coimbatore"]'::jsonb, '["Monthly habit builders", "Corporate meal prep", "Long-term fitness goals"]'::jsonb, 'Best Value', false, 3)
) v(slug, name, type, mpd, days, tagline, description, features, ideal_for, badge, popular, sort)
on conflict (slug) do nothing;

