) v(code, description, dtype, value, min_order, max_discount)
on conflict (code) do nothing;

-- FAQs (data/faqs.json)
insert into public.faqs (question, answer, sort_order)
select v.question, v.answer, v.sort from (values
  ('How are your calories and protein measured?', 'Every recipe is developed with exact raw ingredient weighing in our central kitchen. We weigh portions with commercial digital scales during plating. The numbers on our labels are precise dietary approximations (within ±5-8% natural variance) and are being submitted for accredited NABL lab nutritional analysis.', 0),
  ('What are your delivery slots and cutoff timings in Coimbatore?', 'We deliver Monday through Saturday (6 days a week, Sunday kitchen deep clean). Morning is delivered between 7:00 AM – 9:00 AM, and Dinner between 7:00 PM – 9:00 PM. To ensure zero food wastage and farm-fresh procurement, meal swaps or pauses must be submitted by 9:00 PM the previous evening.', 1),
  ('Can I pause my subscription if I am travelling out of Coimbatore?', 'Yes! You can pause your subscription with one tap in the app under ''Subscription'' or via WhatsApp. Any unused days roll forward or are credited back to your account balance.', 2),
  ('Are the containers microwave-safe and eco-friendly?', 'Yes. Our food trays are 100% food-grade, BPA-free, and microwave safe. We also offer a premium returnable stainless steel insulated tiffin box tier for long-term monthly subscribers who prefer zero plastic.', 3),
  ('What if I have food allergies or dislikes?', 'When you complete our onboarding quiz or use the Meal Builder, you can select your allergies (e.g., Dairy, Nuts, Gluten, Eggs, Soy). Our smart menu engine automatically excludes any dish containing your allergens and highlights free-from choices.', 4),
  ('Is this bland boiled diet food?', 'Not at all! We believe diet food fails when it lacks taste. Our kitchen uses traditional Tamil Nadu spices, cold-pressed sesame and groundnut oils in measured grams, fresh curry leaves, and stone-ground masalas. You get deep authentic taste with exact macro control.', 5)
) v(question, answer, sort)
where not exists (select 1 from public.faqs f where f.question = v.question);

